-- Repaired generator quoting of expression commas before first application.
CREATE INDEX `idx_budget_order_recent` ON `budget_rows` (`mode`,`service`,`fiscal_year`,`is_active`,snapshot_date DESC,`source_key`);--> statement-breakpoint
CREATE INDEX `idx_budget_order_org` ON `budget_rows` (`mode`,`service`,`fiscal_year`,`is_active`,`org`,`project`,`source_key`);--> statement-breakpoint
CREATE INDEX `idx_budget_order_amount` ON `budget_rows` (`mode`,`service`,`fiscal_year`,`is_active`,CASE WHEN CASE WHEN json_extract(row_json,'$.invalid_amount')=1 THEN NULL ELSE COALESCE(json_extract(row_json,'$.budget_amount'),json_extract(row_json,'$.appropriation_amount')) END IS NULL THEN -1 WHEN substr(CASE WHEN json_extract(row_json,'$.invalid_amount')=1 THEN NULL ELSE COALESCE(json_extract(row_json,'$.budget_amount'),json_extract(row_json,'$.appropriation_amount')) END,1,1)='-' THEN 0 ELSE 1 END DESC,CASE WHEN substr(CASE WHEN json_extract(row_json,'$.invalid_amount')=1 THEN NULL ELSE COALESCE(json_extract(row_json,'$.budget_amount'),json_extract(row_json,'$.appropriation_amount')) END,1,1)='-' THEN -length(substr(CASE WHEN json_extract(row_json,'$.invalid_amount')=1 THEN NULL ELSE COALESCE(json_extract(row_json,'$.budget_amount'),json_extract(row_json,'$.appropriation_amount')) END,2)) ELSE length(CASE WHEN json_extract(row_json,'$.invalid_amount')=1 THEN NULL ELSE COALESCE(json_extract(row_json,'$.budget_amount'),json_extract(row_json,'$.appropriation_amount')) END) END DESC,CASE WHEN substr(CASE WHEN json_extract(row_json,'$.invalid_amount')=1 THEN NULL ELSE COALESCE(json_extract(row_json,'$.budget_amount'),json_extract(row_json,'$.appropriation_amount')) END,1,1)<>'-' THEN CASE WHEN json_extract(row_json,'$.invalid_amount')=1 THEN NULL ELSE COALESCE(json_extract(row_json,'$.budget_amount'),json_extract(row_json,'$.appropriation_amount')) END END DESC,CASE WHEN substr(CASE WHEN json_extract(row_json,'$.invalid_amount')=1 THEN NULL ELSE COALESCE(json_extract(row_json,'$.budget_amount'),json_extract(row_json,'$.appropriation_amount')) END,1,1)='-' THEN substr(CASE WHEN json_extract(row_json,'$.invalid_amount')=1 THEN NULL ELSE COALESCE(json_extract(row_json,'$.budget_amount'),json_extract(row_json,'$.appropriation_amount')) END,2) END ASC,`source_key`);--> statement-breakpoint
CREATE INDEX `idx_budget_order_remaining` ON `budget_rows` (`mode`,`service`,`fiscal_year`,`is_active`,CASE WHEN json_extract(row_json,'$.remaining_amount') IS NULL THEN -1 WHEN substr(json_extract(row_json,'$.remaining_amount'),1,1)='-' THEN 0 ELSE 1 END DESC,CASE WHEN substr(json_extract(row_json,'$.remaining_amount'),1,1)='-' THEN -length(substr(json_extract(row_json,'$.remaining_amount'),2)) ELSE length(json_extract(row_json,'$.remaining_amount')) END DESC,CASE WHEN substr(json_extract(row_json,'$.remaining_amount'),1,1)<>'-' THEN json_extract(row_json,'$.remaining_amount') END DESC,CASE WHEN substr(json_extract(row_json,'$.remaining_amount'),1,1)='-' THEN substr(json_extract(row_json,'$.remaining_amount'),2) END ASC,`source_key`);
